# Homebrew formula for cc-notes. Installs the prebuilt binary for the current
# platform from cc-notes' GitHub Releases — no Go toolchain needed.
#
#   brew install yasyf/tap/cc-notes
#
# Asset names, scripts/install.sh, and the render-formula substitutions in
# .github/workflows/release.yml must change in lockstep.
#
# GENERATED by cc-notes' release.yml (render-formula) from this template — edit the
# template at .github/formula/cc-notes.rb.tmpl, not the tap copy.
class CcNotes < Formula
  desc "Git-native notes and tasks layer for agents"
  homepage "https://github.com/yasyf/cc-notes"
  version "0.75.21"
  license "PolyForm-Noncommercial-1.0.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    resource "helper" do
      url "https://github.com/yasyf/cc-notes/releases/download/v0.75.21/cc-notes-helper-v0.75.21-darwin.zip", using: :nounzip
      sha256 "f6bc32626824e8e6932a129c8a27974c9425c6c39beac2df6b37920a234deb6a"
    end

    on_arm do
      url "https://github.com/yasyf/cc-notes/releases/download/v#{version}/cc-notes_darwin_arm64"
      sha256 "8f2fbb317a1548330330061658eae9f389e264d216b2650e4d50a6e073b94bca"
    end
    on_intel do
      url "https://github.com/yasyf/cc-notes/releases/download/v#{version}/cc-notes_darwin_amd64"
      sha256 "36e69467a0461c4c4114d2905d1e1140b94694e71a2a6644f4c31708fe130857"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/yasyf/cc-notes/releases/download/v#{version}/cc-notes_linux_amd64"
      sha256 "37e46e7d64ded1ba8a981a1060bd075ab9dd745c9afe43c7c0b5304a4eda9986"
    end
    on_arm do
      url "https://github.com/yasyf/cc-notes/releases/download/v#{version}/cc-notes_linux_arm64"
      sha256 "abc9afd27d7db65d4fc6d7c1ca3ae452a73b63a482bff09ffd62c27c67fe8ab5"
    end
  end

  preserve_rpath

  def install
    # The release asset is a bare binary staged under its asset name.
    bin.install Dir["cc-notes_*"].first => "cc-notes"
    if OS.mac?
      resource("helper").stage do
        system "/usr/bin/ditto", "-x", "-k", resource("helper").cached_download, "."
        system "/usr/bin/codesign", "--verify", "--strict", "--verbose=2", "CCNotesHelper.app"
        libexec.install "CCNotesHelper.app"
      end
      # opt_libexec, not libexec: Homebrew unlinks the active keg mid-upgrade,
      # and the packaged copy is the one that lands the deployment.
      (bin/"cc-notes-host").write <<~SH
        #!/bin/bash
        exec "#{opt_libexec}/CCNotesHelper.app/Contents/MacOS/CCNotesHelper" "$@"
      SH
    end
    bin.install_symlink "cc-notes" => "ccn"
  end

  def caveats
    return if OS.linux?

    <<~EOS
      Install and activate the fixed signed helper explicitly:
        cc-notes package install
    EOS
  end

  test do
    # Release binaries print "<tag> (<commit>)", e.g. "v0.2.0 (ab12cd3)".
    assert_match version.to_s, shell_output("#{bin}/cc-notes version")
    if OS.mac?
      system "/usr/bin/codesign", "--verify", "--deep", "--strict", "--verbose=2", libexec/"CCNotesHelper.app"
      assert_match version.to_s, shell_output("#{bin}/cc-notes-host version")
    end
  end
end
